INSERT INTO `categories` (`catID`, `title`, `description`, `orderIndex`) VALUES (1,'Yoga Mat Bags','<font color=blue><b> *** Sorry!  We are currently sold out.  Custom orders welcome! <a href=http://www.anayoga.com/contact.php> Click here to order. </a>*** </font></b> <br> Beautiful handmade bags in a variety of high-quality fabrics.  Each bag is unique! ',2),
(8,'Other Yoga Accessories','One-of-a-Kind AnaYoga strap, blocks, meditation and relaxation supplies.',4),
(3,'Totes & Bags','Browse through a beautiful selection of totes, messenger bags, diaper bags and backpacks.  One-of-a-kind bags for you or that special someone!',6),
(4,'Jewelry','Unique handcrafted necklaces, earrings, bracelets, and more.',5),
(7,'*Clearance Items*','Join the <a href=\"contact.php\">AnaYoga.com Mailing List</a> to be notified of product updates and sales.  Clearance items do not last long! ',13),
(12,'Custom Orders','Can\'t find what you\'re looking for?  Consider customizing your order!',10),
(14,'Gift Bags','The next time you give someone a gift, give a gift to the environment as well with these reusable cloth gift bags.<i>  A variety of sizes and fabrics are available.  Those shown here are just a sampling!</i> All prices include shipping to the US/Canada.',7),
(17,'Fabric Selection','Here is a current sampling of fabrics and trims  available for custom orders.  Please note:  In order to continue making one-of-a-kind items, I purchase a wide variety of fabric in small quantities.  All fabrics shown here are available in *limited* amounts only.  Can\'t decide which fabric you\'d like?  I would be happy to suggest fabrics for a given project, <a href=http://www.anayoga.com/contact.php>just ask!</a>',11),
(18,'Gallery','Sit back and take a few minutes to browse through a selection of AnaYoga Originals and custom creations which I have handcrafted for clients in the past.  <b>Everything you see here is happily residing with a new owner and is no longer available for purchase.  You can place your custom order by using the <a href=http://www.anayoga.com/contact.php>\"Contact Me\"</a> link at the top of the page.</b>',12),
(21,'Custom Gift Baskets','Can\'t decide on the perfect gift?  How about a little of everything!  Great prices for exquisite custom-made baskets.  ',9),
(22,'Gift Certificates!','The perfect gift!  Gift certificates are available in any amount you wish to give.  ',8);
INSERT INTO `products` (`prodID`, `name`, `price`, `description`, `imgFileName`, `imgDetailFileName`, `featured`, `category`, `orderIndex`) VALUES (150,'\"Daisy\" Tote Bag',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  Soft brushed cotton tote. Features pretty daisy florals on a light blue background. 100% cotton lining in matching sky blue. This bag is lined with interfacing, giving a sturdy form to the bag and allowing it to stand on its own. Measures approximately 12\" long x 11\" high x 3\" wide. Each handle measures 17\" long (end-to-end).','BluedaisyTote.jpg','bluedaisyCU.jpg',0,18,5),
(91,'Hemp Yoga Strap',14,'Use this one-of-a-kind AnaYoga strap to help ease yourself further into each stretch. A unique patent-pending design!  Made from beautiful unbleached hemp, the wide strap is constructed to ensure comfort and durability. Rings allow you to get a better hold of the strap, so you can focus on each posture. The adjustable buckle makes this strap functional for all levels of flexibility, and lets you easily vary the length for smooth transition between postures. Designed and constructed by myself for my students and yoga practitioners everywhere. Measures approximately 32” and expands to 53” (measured from ring to ring). Custom sizes available, please ask.','yoga strap1.jpg','',0,8,2),
(203,'\"Sunrise Sunset\"',0,'<font color=red> This bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  Soft brushed poly-cotton blend yoga bag. This bag is made from upholstery grade fabric that is both strong and beautiful. The fabric feels velvety to the touch. It features a subtle leaf and geometric pattern on an earthy, safron-coloured background. The strap is a soft and thick 100% unbleached cotton that is carefully hand-braided. The drawstring at the top is made from 100% unbleached hemp, also hand-braided and decorated with matching beads. The easy-to-use black pull cord keeps all your yoga gear secured inside the bag. This bag is roomier than most other yoga bags, and is wide enough to fit a standard sticky mat, blocks, strap, and other small belongings such as a wallet, bottle of water, etc. It measures approximately 13” x 27” with a 27” long handle. ','Sunrise.jpg','sunriseCU.jpg',0,18,3),
(147,'Indigo Paisley',0,'<font color=red> This bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>. This bag is sure to get some attention! It is made of lightweight satin in a rich shade of indigo, and features a flowing paisley design. It feels soft to the touch, and drapes beautifully. This bag requires gentle care and is intended for the yogi who appreciates delicacy. But don’t be mistaken, it is strong enough to carry all your yoga gear. The strap is a soft and thick 100% unbleached cotton that is carefully hand-braided. The drawstring at the top is made of 100% unbleached hemp, also hand-braided and decorated with matching beads (please see detailed photo). The easy-to-use pull cord keeps all your yoga gear secured inside the bag. This bag is roomier than most other yoga bags, and is wide enough to fit a standard sticky mat, blocks, strap, and other small belongings such as a bottle of water, wallet, etc. It measures approximately 12” x 27” with a 27” strap.','IndigoSatin.jpg','indigosatinCU.jpg',0,18,3),
(182,'Amber with Charm (SOLD)',18,'<font color=red>Sorry, this necklace has been purchased.  Please contact me for custom-made pieces.</font>This necklace features honey and amber coloured glass beads strung along a wire.  A small matching stone encased within a wire cage hangs delicately at the bottom.  The lobster claw clasp and loop are securely attached to a metal wire that measures approximately 20\" long.   Shipping to Canada/continental USA included in price.  Will ship worldwide!','amber20001.JPG','',0,4,15),
(25,'\"Crimson Leaves\"',0,'<font color=red>Sorry, this yoga bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order.</font> </font> Another stunning bag, this one is made of 100% polyster.  Strong and flowing, it features a pretty leaf pattern on a deep crimson background.  The strap is a soft and thick 100% unbleached cotton that is carefully hand-braided.  The drawstring at the top is made of 100% unbleached hemp, also hand-braided and decorated with matching beads.  The easy-to-use pull cord keeps all your yoga gear secured inside the bag.  This bag is roomier than most other yoga bags, and is wide enough to fit a standard sticky mat, blocks, strap, and other small belongings such as a bottle of water, wallet, etc.  It measures approximately 13” x 28”with a 27” strap.','AnaYoga012.jpg','AnaYoga12b.jpg',0,18,4),
(345,'\"Metal\" Kanji Necklace',18,'Place description here. \"Metal\" in the Elemental series of one-of-a-kind, handcrafted necklaces. This necklace features the kanji symbol for \"metal\", which is embraced on either side by a string of hematite beads. Hematite is believed to impart good health and positive energy. Measures approximately 18\" in length, with a 1\" extension chain secured with a lobster claw clasp and hook. See others in this series, including \"earth\", \"water\" and \"wood\".','metal.JPG','metalCU.JPG',0,4,10),
(28,'\"Showers of Flowers\"',0,'<font color=red>Sorry, this bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>  This yoga bag is made of a poly-cotton blend fabric, featuring a pretty, multi-coloured floral pattern on a soft beige background.  It is strong and functional.  The strap is a soft and thick 100% unbleached cotton that is carefully hand-braided.  The drawstring at the top is made of 100% unbleached hemp, also hand-braided and decorated with matching beads.  The easy-to-use pull cord keeps your yoga gear secured inside the bag.  This bag is roomier than most other yoga bags, and is wide enough to fit a standard sticky mat with room to spare.  It measures approximately 11” x 28” with a 30” strap.','AnaYoga015.jpg','AnaYoga15b.jpg',0,18,3),
(124,'Hemp and Paisley',0,'<font color=red> This bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>. This bag is made from natural, unbleached hemp fabric. It features a bold, paisley-pattern trim with gold threading. Hemp is an extremely strong and durable fabric. The handle is made of a thick and soft 100% unbleached cotton that is carefully hand-braided. The drawstring is made from 100% unbleached hemp twine that has also been hand-braided, and features an easy-to-use pull cord and matching beads. This bag measures approximately 9” x 26” with a 27” strap.','HempYogaTote 019.jpg','HempYogaCU.jpg',0,18,3),
(178,'The Instructor\'s Tote',0,'Durable construction, attractive fabrics, practical design.  Custom-made for the yoga instructor who needs to carry a lot of equipment from class to class.  This bag is large enough to carry 4 standard yoga mats, with room to spare for blocks and other equipment.  It comes with a separate, matching drawstring pouch to place your shoes, wallet and other small items which tend to slip to the bottom of conventional bags.  Wide nylon straps help distribute the heavy load on your shoulders, while the sleek construction makes this bag completely portable and storable.  Contact me with colour and fabric choices.  Ready for shipping within 5-10 days of placing order. <font color=red> (Please note: Butterfly tote pictured has been purchased.  Many other fabric choices are available.  Contact me for more info). </font>','yogatoteBFLY.jpg','yogatoteIN.jpg',0,18,2),
(169,'Therapeutic Heat/Cool Pack',18,'This pack is made of unbleached hemp, with a decorative lavender coloured trim. The pack contains 100% organic linseed, and can be used cool (store in fridge) or warm (microwave). Linseed, aka “flax seed”, is filled with natural oils and maintains its temperature longer than traditional rice-filled packs. The cover is removable and washable, and features a loop-and-hook (tm “Velcro”) fastener at one end. Measures approximately 4.5” x 19”, and wraps comfortably behind your neck to help relieve tense muscles and headaches. <font color=red> This particular fabric combination has been purchased.  Many others available!</font>','heatpack.jpg','heatpackCU.jpg',0,8,4),
(142,'Lavender Scented Eye Pillow',14,'Use this eye pillow to help soothe and comfort sore, tired eyes. Let the gentle weight of linseeds rest on your eyes during relaxation or meditation, and allow the soothing scent of lavender to clear and calm your mind. The cover is made of hemp on one side, and a cool satin on the other. It is removable and washable, with loop-and-hook (tm “Velcro”) fasteners at one end. The pouch is filled with 100% organic linseed, and pure, fragrant lavender buds.  For those with sensitivities, the lavender buds can be excluded upon request.','eyepillow.jpg','eyepillowCU.jpg',0,8,5),
(213,'\"Green Beauty\" (SOLD)',15,'<font color=red>Sorry, this necklace has been purchased.</font> <p> Even more stunning in person! You have to see and feel this necklace to appreciate it. The heavy and cool sensation of the stones can not be seen in the photo. This necklace features a mixture of green semi-precious stones of various shapes and sizes arranged to create a beautiful necklace. This necklace can be worn casual with a t-shirt, or dressed up as an accent for a special occasion. A small matching stone encased within a wire cage hangs delicately at the bottom. <p>The lobster claw clasp and loop are securely attached to a metal wire that measures approximately 20\" long.  ','greenbeauty0001.JPG','',0,7,5),
(64,'Custom Orders',0,'I do custom orders.  Please <a href=\"contact.php\">contact me </a>for more information.  Previous custom orders for clients have included specialized sporting bags (such as the kendo martial arts bag pictured here), tote and gift bags with personalized photos, custom-sized yoga bags, straps, blocks and clothing for all ages and sizes.','AnaYoga 036.jpg','',0,12,1),
(352,'\"Fire\" Kanji',0,'<font color=red>Sorry, this item has been purchased.</font> \"Fire\" in the Elemental series of one-of-a-kind, handcrafted necklaces. This necklace features the kanji symbol for \"fire\", which is embraced on either side by a string of high-quality beads which flicker with rich red, yellow and orange tones. Measures approximately 18\" in length, with a 1\" extension chain secured with a lobster claw clasp and hook. ','firekanji0001.JPG','firekanji0002.JPG',0,18,11),
(351,'\"Love\" Kanji Necklace',18,'\"Love\" in the Elemental series of one-of-a-kind, handcrafted necklaces. This necklace features the kanji symbol for \"love\", which is embraced on either side by a string of high quality, red glass beads. Measures approximately 18\" in length, with a 1\" extension chain secured with a lobster claw clasp and hook. ','lovekanji0001.JPG','lovekanji0002.JPG',0,4,5),
(79,'\"Golden Leaves\"',0,'<font color=red>Sorry, this bag has been purchased.</font> This bag is one of my absolute favourites. It is made from a golden sateen upholstery grade material. It is strong and beautiful, featuring small, golden leaves delicately raised above the fabric. The strap is a soft and thick 100% unbleached cotton that is carefully hand-braided. The drawstring at the top is made of 100% unbleached hemp, also hand-braided and decorated with matching beads. The easy-to-use golden pull cord keeps all your yoga gear secured inside the bag. This bag is roomier than most other yoga bags, and is wide enough to fit a standard sticky mat with room to spare. It measures approximately 11” x 27” with a 27” strap.','AnaYoga 011.jpg','AnaYoga 11b.jpg',0,18,3),
(200,'Nylon Yoga Strap',14,'Use this one-of-a-kind AnaYoga strap to help ease yourself further into each stretch. A unique, patent-pending design!  Wide nylon construction ensures comfort and durability. Rings allow you to get a better hold of the strap, so you can focus on each posture. The adjustable buckle makes this strap functional for all levels of flexibility, and lets you easily vary the length for smooth transition between postures. Designed and constructed by myself for my students and yoga practitioners everywhere. Measures approximately 20” and expands to 33” (measured from ring to ring). Custom sizes also available, please ask.','nylonstrap.jpg','nylonstrapCU.jpg',0,8,3),
(367,'\"Blue Bird\" necklace',20,'This little birdie is the bringer of good news!  Do you have some exciting news to share with a loved one?  Celebrating a special event?  This little bird will carry your message in style, specially gift-wrapped and personalized with a note of your choice!  \r\n<p>Handcrafted using high quality beads on a strong wire, securely attached to an elegant toggle clasp which features a heart motif. The necklace, measured from end-to-end is approximately 20\" long. <p>\r\nShipping to Canada/continental USA included in price. \r\n','neckbird.JPG','neckbirdCU.JPG',0,4,3),
(88,'Wooden Yoga Blocks',15,'<font color=blue>Sorry, these yoga blocks are currently out of stock.  New, improved blocks will soon be available!  <a href=http://www.anayoga.com/contact.php> Join the mailing list here</a> to be notified of product updates!</font><p>These solid wood blocks are made of cedar, a very strong and lightweight material. The wood for these blocks have been harvested from ecologically intact forests (NO CLEARCUTTING!). Furthermore, these blocks have NOT been chemically treated. They have been hand-sanded for a smooth finish. <p>Because these blocks have not been treated with chemicals or paint, the following care is recommended: *Store away from direct sunlight *Avoid exposure to drastic changes in humidity *Minor \"imperfections\" such as knots are a beautiful and natural characteristic of wood. Such knots may be present in the finish of your block so as not to waste any part of the tree. Standard size available: 3x6x9\". Custom sizes can also be ordered. <font color=red>$15 each or $28 a pair. Shipping extra.</font>','yogablocks.jpg','',0,8,6),
(359,'\"Sakura\"  Bag (SOLD)',35,'<font color=red>Sorry.  This one-of-a-kind bag has been purchased.</font> <p>Sakura, the Japanese word for \"Cherry Blossom\" is a symbol of peace and friendship.  \"Sa\" means god of the paddies and \"Kura\" means the place of the God. \"SAKURA\" is a place where the god of the paddies is present. From ancient times, people have gathered under blossoming cherry trees to celebrate spring and life. <p>This bag is all-natural jute.  I have painted cherry blossoms on the front, along with the kanji symbol for sakura.  This bag measures approx. 14\"x11\" with a WIDE 8\" base, very roomy! Perfect for trips to the beach, or as a craft/knitting bag! The handles are wooden, and reminiscent of the famous pagodas in Japan.<p>\r\n\r\nThe trim around the bag has been adorned with a pretty cherry and leaf motif.  The special fabric paint has been \"set\" and will not run or smudge.  <p>FREE SHIPPING TO CANADA/US!','sakura1.jpg','sakura2.jpg',0,3,13),
(154,'\"Libra\" Necklace',0,'<font color=red>Sorry, this item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font> <font color=blue>Libra (September 24-October 23) </font>This necklace is \"Libra\" in a series of fun zodiac charm necklaces. The necklace features a high-quality pewter alloy \"Scales\" on a metal wire necklace. The charm has the engraved zodiac symbol on both sides! Please see the detailed photo on right to get a closer look. Lobster claw clasp and hook attach the ends. Measures approximately 18\" long. <font color = red>Regular Price: $19.99</font>','libra0001.JPG','libra0002.JPG',0,18,6),
(208,'Batik Yoga Bag',0,'<font color=red> This bag has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  Beautiful batiks! 100% cotton with blending shades of gorgeous colour. Fully lined (see photos) and matching detailed trim on strap and drawstring. Carefully topstitched for durability and for that professionally tailored look! This bag is wide enough to fit a standard yoga mat, with room to spare. Measures approximately 12\"x30\", with a drawstring and clasp closure to keep your items secure. This particular bag is sold, however I will personalize your bag with your colour preferences at no extra charge. ($39.99 each)','batikyogabag.jpg','batikyogabagCU.jpg',0,18,3),
(347,'\"Sandstone\" Hemp',8,'<font color=red>Regular Price $10, Clearance Price $8, shipping to US/Canada included!</font><p>This necklace has been handcrafted from 100% hemp twine, and adorned with \"sandstone\" beads. Simple, crisp and neutral, this 16\" choker-style necklace is sure to complement any outfit. ','sandyhemp.JPG','sandyhempCU.JPG',0,7,15),
(348,'\"Voodoo\" Hemp',8,'<font color=red>Regular price $10, Clearance price is $8, shipping to US/Canada included!</font><p> This 16\" choker style necklace has been carefully handcrafted, one knot at a time, using 100% hemp twine. It features five high quality beads with intricate markings and a ball-and-loop closure. ','voodoo.JPG','voodooCU.JPG',0,7,16),
(356,'\"Moda\" Tote Set (SOLD)',45,'<font color=blue>Sorry, this item has been purchased.</font> This tote set is one-of-a-kind!  It has been handcrafted using 100% cotton buttery-soft velour fabric in cool blue stripes. Take a peek inside this bag and you\'ll see a 100% cotton print featuring stylish fashionistas sipping on coffee, chatting on the phone, and taking their pooches on a stroll.  This luxurious soft tote has a handy key clip and a magnetic snap closure to keep your belongings secure.  This set also includes a matching zippered makeup pouch! The tote measures a roomy 13\"x11\"x4\" with a 23\" long strap, and the pouch measures approximately 6\"x7\".  ','bagset1.jpg','bagset7.jpg',0,3,4),
(115,'\"Checkered\" Tote',38,'This tote is truly unique. It is made of a rich brown and black checkered fabric with detailed stitching, creating a slightly raised, quilted effect. The exterior is a poly blend that catches the light and shimmers ever so slightly. The lining is a beautiful copper satin fabric, and includes a small inner pocket. This bag is lined with lightweight interfacing, lending the bag support while allowing a fluid soft movement. Measures approximately 12\" long x 11\" high x 3\" wide. Each handle measures 17\" long (end-to-end).  Shipping to Canada/continental USA included in price. Worldwide shipping is also available!','checkTote.jpg','',0,3,4),
(117,'\"Blue Orient\"',0,'<font color=red>Sorry, this item has been purchased</font>  Made from 100% cotton, this blue tote has a gorgeous golden oriental-inspired filigree pattern throughout. Open the bag and you will see a beautiful royal purple lining, as well as a small inner pocket. The contrast between the blue and deep purple is eye-catching, and is also apparent on the underside of each handle. Please see the detailed photo for a close-up of this tote! This bag is lined with interfacing, lending the bag support so that it can stand on its own. Measures approximately 12\" long x 11\" high x 3\" wide. Each handle measures 17\" long (end-to-end).','bluebag.jpg','insideblue.jpg',0,18,5),
(139,'Diaper Bag & Pad',70,'This is a diaper bag I custom-designed for a client. It consists of one large main compartment, a small inner pocket, two outer sippy-cup/bottle pockets with elasticized tops, and a key ring/pacifier loop at the top of the bag to keep these smaller items from getting lost at the bottom. The matching change pad has a removable, machine-washable cover encasing a waterproof padding. Each bag has interfacing to lend support and strength to the bag. I make these diaper bags one at a time, to your specifications for fabric and features. Please use the \"Contact Me\" link to place your order, or to have any questions answered.  Shipping to Canada/continental USA included in price. Worldwide shipping is also available!</font>','toiledipebag2.JPG','',0,3,2),
(170,'Bolsters',25,'These bolsters are handmade, and can be used to support the neck, lower back or knees during reclined postures, or as a decorative accent in your home! Made with a breathable and durable hypo-allergenic poly fill, enclosed in 100% unbleached hemp. The luxurious satin cover is removable and washable, and is available in your choice of fabrics. Contact me for other fabrics, I\'d be happy to find the perfect shade for you. Measures approximately 6\" diameter x 17\" length.  Sold individually.','bolsters.jpg','bolsters2.jpg',0,8,1),
(146,'Turquoise Necklace',0,'<font color=red>This particular necklace has already been purchased.  Similar jewelry can be custom made using the same stones you see here.  Use the \"Contact Me\" link at the top right of this page to order. </font> Beautiful turquoise glass beads, delicately interspersed by light blue glass beads that catch the light.  This necklace has a gentle weight to it, and caresses the neck with a cool stone sensation.','torquoiseneck0001.JPG','',0,18,16),
(181,'\"Silver Belle\" Tote',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>. This tote is made of a beautiful silver satin material featuring a delicate black intertwined floral pattern throughout. Inside the bag is a matching grey fabric, and a small inner pocket. This bag is lined with interfacing, lending the bag support so that it can stand on its own. Measures approximately 12\" long x 11\" high x 3\" wide. Each handle measures 17\" long (end-to-end).','silverbag.jpg','insilver.jpg',0,18,5),
(184,'\"Golden Locket\" Necklace',0,'<font color=red>This necklace has been purchased.</font>  This necklace features a large 1.5\" golden locket which opens and closes with room inside for 2 photos.  The locket is adorned with swirling golden details and 7 sparkling gems. The cord is a strong black rope with a clasp closure securely attached. The necklace measures approximately 16\" in length.','blkchokerLocket0001.JPG','',0,18,6),
(189,'\"Honey\" Beads',0,'<font color=red>Sorry, this item has been purchased</font>  This \"sweet\" little necklace features high quality honey and amber-coloured glass beads strung along a metal wire. The lobster claw clasp and loop are securely attached to a metal wire that measures approximately 20\" long.','necklaceamber0001.JPG','',0,18,17),
(214,'Sling Bag',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>. A totally new and unique design!  Extra-wide strap for comfort, deep pouch for carrying everything you\'ll need, and a beautiful floral print that is sure to get noticed!  This bag is fully lined, and has an inner pocket for small items that tend to slip towards the bottom of your bag.  For more photos of this bag, contact me and I will e-mail them to you!  ','slingbag.jpg','slingbagside.jpg',0,18,5),
(224,'Messenger Bag',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  A beautiful, soft faux suede messenger-style bag.  Featuring a luxurious copper-coloured satin lining and two outer pockets.  ','fauxsuedeMB.jpg','fauxMBopenflap.jpg',0,18,5),
(225,'Messenger Bag',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>. This bag is one of my favourites.  Made from 100% cotton, the outside of the bag is a soft blue corduroy.  Peek inside, and you will see an elegant toile lining, also 100% cotton.  This bag measures approximately 11\"x15\"x4\", with a 45\" long strap.  The strap is just under 2\" wide, so it sits comfortably on one shoulder or across your chest.  One outer pocket runs flush with the front of the bag, making this bag sleek, stylish and functional!  ','toilebluecord.jpg','toilebluecordIN.jpg',0,18,5),
(226,'Messenger Bag',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  Soft 100% cotton corduroy exterior, and an earthy striped interior.  This one-of-a-kind bag features one outer pocket, and one large compartment to hold all your items. Beautifully soft to the touch, with a wide and comfortable strap.    ','blackMB.jpg','blackMBin.jpg',0,18,5),
(230,'AnaYoga Custom Totes!',35,'<font color=blue>You be the designer and I\'ll do the rest! </font> Each tote comes fully lined, with a small inner pocket.  Need more features?  Extra pockets?  Water bottle holder?  Change pad?  Magnetic snap or zipper closure?  Let me know and I will customize your bag to your exact specifications.  <a href=http://www.anayoga.com/contact.php> Click here to place your order! </a>Prices start at just $35, shipping to Canada/continental USA included!  ','toiletote.jpg','dottytote.jpg',0,3,1),
(232,'\"Dragon, the Protector\"',0,'<font color=red> This item has been purchased.  Use the \"Contact Me\" link at the top right of this page to place a custom order</font>.  In China, the mythological symbol of the Dragon dates back to 3000 BC.  Dragons were believed to be protectors and to ward off evil spirits.  This necklace features 5 unique beads from the orient, flanked on each end by 2 red dragons.  In numerology, a life path \"5\" is a person who is very versatile and adventurous.  This necklace is a perfect gift for that free-spirited, adventurous friend...who could sometimes use a little friendly protection of the dragon-kind!  This necklace measures approximately 5\" in diameter, and is mounted on a tension wire which expands and contracts to fit around the neck.  ','tensionOrientNkl0001.JPG','tensionOrient0001.JPG',0,18,17),
(234,'100% Cotton - Blue Batik',0,'Beautiful 100% cotton batik fabric with floral motif throughout.  Softly blending shades of blue.  ','bluebatik.jpg','',0,17,4),
(236,'Cotton/Poly Blend - Blue Dane',0,'Cotton/Poly Blend.  Dark blue background featuring dots (\"stippling\") and a flowing floral pattern in a blue-white print.','blue and white0001.JPG','',0,17,22),
(238,'Children\'s Iron-Ons/Appliques',0,'Fun selection of small (approx. 1.5\") iron-on appliques.  Choose from Snowman, Bear, Santa, Whale, Elephant, Fish, Reindeer, Stocking, and Tree.','emb0002.JPG','',0,17,38),
(239,'Blend - Little Roses',0,'Very soft and flowing woven fabric, featuring small rosebuds on a dark burgundy background.  Fabric has a slight sheen to it, not visible in photo.','epFlowers0001.JPG','',0,17,23),
(241,'Blend - India Paisley',0,'This fabric will work beautifully lining the inside of a tote, or on the outside of a yoga mat bag.  Dark, earthy brown paisley swirls.  ','indiapaisley0001.JPG','',0,17,24),
(266,'100% Cotton - Clovers',0,'100% cotton, green clovers on a black background.  There are golden highlights throughout, making this fabric unique!  Not just for St.Patrick\'s Day, we could all use a little \"luck of the Irish\" on any day!','clover.JPG','',0,17,31),
(244,'Blend - Silver Filigree',0,'This will make an elegant handbag clutch or drawstring purse.  Silver woven fabric with a very slight stretch, with a raised \"swirling\" filigree textured throughout.  Catches the light beautifully.','silverswirl0002.JPG','',0,17,23),
(245,'Unbleached Hemp and Cotton',0,'Unbleached hemp, cotton or hemp/cotton blends available.  This fabric is just as named, completely unbleached.  Variety of thicknesses/weaves available (such as muslin, canvas, etc).  ','ubcotton0001.JPG','',0,17,1),
